// FIND DD TASK WITH RETRY TRACKING
const tasks = $input.first().json.result || [];
console.log(`🔍 Scanning ${tasks.length} Kanboard tasks`);

let validTask = null;
for (const task of tasks) {
  const title = task.title ? task.title.toString() : '';
  const description = task.description ? task.description.toString() : '';

  if (title.toLowerCase().includes('due diligence:') && description.includes('http')) {
    const companyName = title.replace(/due diligence:\s*/i, '').trim();
    const websiteMatch = description.match(/https?:\/\/[^\s]+/);
    const websiteUrl = websiteMatch ? websiteMatch[0] : null;

    if (companyName && websiteUrl) {
      validTask = {
        kanboard_id: task.id,
        title: title,
        description: description,
        company_name: companyName,
        website_url: websiteUrl,
        project_id: task.project_id || 1,
        maker_retry_count: 0,
        max_retries: 3
      };
      break;
    }
  }
}

if (!validTask) {
  console.log('ℹ️ No valid Due Diligence tasks found');
  throw new Error('No Due Diligence tasks found');
}

console.log(`🎯 Selected Task: ${validTask.company_name}`);

return {
  json: {
    ...validTask,
    workflow_action: 'VALIDATE_PREREQUISITES'
  }
};

// VALIDATE PREREQUISITES
const taskData = $('Find DD Task').first().json;

console.log(`📋 Validating prerequisites for: ${taskData.company_name}`);

const missingItems = [];

if (!taskData.title.toLowerCase().includes('due diligence:')) {
  missingItems.push('Title must start with "Due Diligence: [Company Name]"');
}

if (!taskData.website_url) {
  missingItems.push('Description must contain the official website URL');
}

if (missingItems.length > 0) {
  console.log(`❌ Missing prerequisites: ${missingItems.length} items`);
  return {
    json: {
      ...taskData,
      prerequisites_valid: false,
      missing_items: missingItems,
      workflow_action: 'POST_MISSING_COMMENT'
    }
  };
}

console.log('✅ All prerequisites valid');
return {
  json: {
    ...taskData,
    prerequisites_valid: true,
    workflow_action: 'BUILD_KNOWLEDGE_BASE'
  }
};

// BUILD COMPREHENSIVE KNOWLEDGE BASE
const taskData = $('Validate Prerequisites').first().json;

// Get user comments (critical for context)
let userComments = [];
try {
  const commentsResponse = $('Get Comments').first();
  if (commentsResponse && commentsResponse.json && commentsResponse.json.result) {
    userComments = commentsResponse.json.result.filter(comment => 
      !comment.comment.includes('SECTION COMPLETED') && 
      !comment.comment.includes('PREREQUISITES MISSING')
    );
    console.log(`📋 Found ${userComments.length} user comments`);
  }
} catch (error) {
  console.log(`⚠️ Comments fetch failed: ${error.message}`);
}

// Get attachments
let attachments = [];
try {
  const attachResponse = $('Get Attachments').first();
  if (attachResponse && attachResponse.json && attachResponse.json.result) {
    attachments = attachResponse.json.result;
    console.log(`📎 Found ${attachments.length} attachments`);
  }
} catch (error) {
  console.log(`⚠️ Attachments fetch failed`);
}

// Get website content
let websiteContent = '';
try {
  const websiteResponse = $('Fetch Website').first();
  if (websiteResponse && websiteResponse.json) {
    websiteContent = websiteResponse.json.toString();
  } else if (websiteResponse && websiteResponse.data) {
    websiteContent = websiteResponse.data.toString();
  }
} catch (error) {
  console.log(`⚠️ Website fetch failed`);
}

// Get FinBERT analysis
let finbertData = null;
try {
  const finbertResponse = $('Run FinBERT').first();
  if (finbertResponse && finbertResponse.json) {
    finbertData = finbertResponse.json;
  }
} catch (error) {
  console.log(`⚠️ FinBERT failed`);
}

console.log(`📚 Building Knowledge Base for: ${taskData.company_name}`);

// Create knowledge base chunks
let kbChunks = [];

// Task info chunks (always include)
kbChunks.push({
  chunk_id: `kb://${taskData.kanboard_id}/task:title`,
  content: `Company: ${taskData.company_name}. Task: ${taskData.title}`,
  source_type: 'task_info'
});

kbChunks.push({
  chunk_id: `kb://${taskData.kanboard_id}/task:description`,
  content: `Task Description: ${taskData.description}`,
  source_type: 'task_info'
});

// User comments (prioritized)
userComments.forEach((comment, index) => {
  kbChunks.push({
    chunk_id: `kb://${taskData.kanboard_id}/user:${comment.username || 'user'}_${index}`,
    content: `User Input from ${comment.username}: ${comment.comment}`,
    source_type: 'user_input'
  });
});

// Website chunks
if (websiteContent) {
  const chunks = chunkText(websiteContent, 800);
  chunks.forEach((chunk, index) => {
    kbChunks.push({
      chunk_id: `kb://${taskData.kanboard_id}/website:${index + 1}`,
      content: chunk,
      source_type: 'website'
    });
  });
}

// Attachment info
attachments.forEach((file, index) => {
  kbChunks.push({
    chunk_id: `kb://${taskData.kanboard_id}/file:${file.name}`,
    content: `Attachment: ${file.name} (${file.size} bytes) - Available for analysis`,
    source_type: 'attachment'
  });
});

// FinBERT analysis
if (finbertData) {
  kbChunks.push({
    chunk_id: `kb://${taskData.kanboard_id}/finbert:analysis`,
    content: `FinBERT Financial Analysis: ${JSON.stringify(finbertData)}`,
    source_type: 'finance'
  });
}

function chunkText(text, maxTokens) {
  const words = text.split(/\s+/);
  const chunks = [];
  let currentChunk = [];

  for (const word of words) {
    currentChunk.push(word);
    if (currentChunk.length >= maxTokens * 0.75) {
      chunks.push(currentChunk.join(' '));
      currentChunk = [];
    }
  }

  if (currentChunk.length > 0) {
    chunks.push(currentChunk.join(' '));
  }

  return chunks;
}

console.log(`📊 Knowledge Base: ${kbChunks.length} chunks`);

return {
  json: {
    ...taskData,
    kb_chunks: kbChunks,
    user_comments_count: userComments.length,
    attachments_count: attachments.length,
    total_chunks: kbChunks.length,
    workflow_action: 'GENERATE_MAKER_PROMPT'
  }
};

// GENERATE MAKER PROMPT WITH RETRY LOGIC
const taskData = $input.first().json;
const kbChunks = taskData.kb_chunks || [];
const retryCount = taskData.maker_retry_count || 0;

const sectionName = "Business Model & Unit Economics";

// Prioritize user input and task info
const userChunks = kbChunks.filter(chunk => ['user_input', 'task_info'].includes(chunk.source_type));
const otherChunks = kbChunks.filter(chunk => !['user_input', 'task_info'].includes(chunk.source_type));
const prioritizedChunks = [...userChunks, ...otherChunks.slice(0, 5)];

const kbText = prioritizedChunks.map(chunk => 
  `[${chunk.chunk_id}]: ${chunk.content.substring(0, 500)}...`
).join('\n\n');

let retryInstructions = '';
if (retryCount > 0) {
  retryInstructions = `\n\nRETRY #${retryCount}: Previous attempt failed. Focus on being more specific and cite sources properly.`;
}

const makerPrompt = `SYSTEM:
You are the MAKER agent for Due Diligence. Write ONLY the Business Model & Unit Economics section.
Use ONLY the provided Knowledge Base. Do not invent data. Cite sources as [KB:chunk_id].
If data is missing, state "Insufficient evidence in KB for [specific item]".
${retryInstructions}

USER:
Company: ${taskData.company_name}
Website: ${taskData.website_url}

Knowledge Base (${prioritizedChunks.length} chunks):
${kbText}

Write the "${sectionName}" section covering:
1. Value Proposition - How the company creates value
2. Revenue Streams - Primary revenue sources
3. Pricing Strategy - How products/services are priced
4. Key Cost Drivers - Major operational costs
5. Unit Economics - CAC, LTV, margins (if available in KB)

Requirements:
- Professional Markdown format
- Cite every fact with [KB:chunk_id]
- If missing data, state "Insufficient evidence in KB"
- Focus only on evidence from KB chunks`;

console.log(`📝 Maker prompt generated (Retry: ${retryCount})`);

return {
  json: {
    ...taskData,
    section_name: sectionName,
    maker_prompt: makerPrompt,
    workflow_action: 'RUN_MAKER'
  }
};

// CHECKER WITH AUTO-RETRY LOGIC
const taskData = $('Generate Maker Prompt').first().json;
const makerResponse = $input.first().json.response;
const retryCount = taskData.maker_retry_count || 0;
const maxRetries = taskData.max_retries || 3;

console.log(`📝 Checking Maker output (${makerResponse.length} chars, retry ${retryCount})`);

const kbChunks = taskData.kb_chunks || [];
const citedChunks = kbChunks.filter(chunk => 
  makerResponse.includes(chunk.chunk_id)
);

const checkerPrompt = `SYSTEM:
You are the CHECKER. Validate if the Maker's work is acceptable.
Approve if it shows effort and properly indicates missing data.
Reject only for clear hallucinations or completely unsupported claims.

USER:
Maker Output:
${makerResponse}

Available KB:
${kbChunks.slice(0, 5).map(chunk => `[${chunk.chunk_id}]: ${chunk.content}`).join('\n\n')}

Validation:
1) Claims supported by KB OR marked as "Insufficient evidence"
2) No invented data
3) Proper [KB:chunk_id] citations
4) Professional quality

Respond ONLY in JSON:
{
  "approved": true|false,
  "quality_score": <1-10>,
  "issues": ["problems if any"],
  "instructions_for_maker": "guidance"
}`;

return {
  json: {
    ...taskData,
    maker_output: makerResponse,
    checker_prompt: checkerPrompt,
    workflow_action: 'RUN_CHECKER'
  }
};

// SMART RETRY DECISION - NO SPAM
const taskData = $('Prepare Checker').first().json;
const checkerResponse = $input.first().json.response;
const retryCount = taskData.maker_retry_count || 0;
const maxRetries = taskData.max_retries || 3;

let checkerDecision;
try {
  checkerDecision = JSON.parse(checkerResponse);
} catch (error) {
  checkerDecision = {
    approved: false,
    quality_score: 1,
    issues: ['Invalid Checker response'],
    instructions_for_maker: 'Retry with clearer output'
  };
}

console.log(`🔍 Checker: ${checkerDecision.approved ? 'APPROVED' : 'REJECTED'} (Score: ${checkerDecision.quality_score}/10)`);

if (!checkerDecision.approved) {
  if (retryCount >= maxRetries) {
    console.log(`❌ Max retries exceeded`);
    return {
      json: {
        ...taskData,
        checker_decision: checkerDecision,
        workflow_action: 'POST_FAILURE_COMMENT'
      }
    };
  }

  // SILENT RETRY - no comment spam
  console.log(`🔄 Retrying silently (${retryCount + 1}/${maxRetries})`);
  return {
    json: {
      ...taskData,
      maker_retry_count: retryCount + 1,
      checker_decision: checkerDecision,
      workflow_action: 'RETRY_MAKER'
    }
  };
}

// Approved - run Approver
const approverPrompt = `SYSTEM:
You are the APPROVER. Final business review.

USER:
Maker Output:
${taskData.maker_output}

Checker Score: ${checkerDecision.quality_score}/10

Approve if:
- Strategic value for executives
- Professional quality
- Honest about limitations

Respond ONLY in JSON:
{
  "approved": true|false,
  "final_feedback": "brief rationale"
}`;

return {
  json: {
    ...taskData,
    checker_approved: true,
    checker_decision: checkerDecision,
    approver_prompt: approverPrompt,
    workflow_action: 'RUN_APPROVER'
  }
};

