// FINAL APPROVAL DECISION
const taskData = $('Process Checker').first().json;
const approverResponse = $input.first().json.response;

let approverDecision;
try {
  approverDecision = JSON.parse(approverResponse);
} catch (error) {
  approverDecision = {
    approved: false,
    final_feedback: 'Invalid Approver response'
  };
}

console.log(`✅ Approver: ${approverDecision.approved ? 'APPROVED' : 'REJECTED'}`);

if (!approverDecision.approved) {
  const retryCount = taskData.maker_retry_count || 0;
  const maxRetries = taskData.max_retries || 3;

  if (retryCount >= maxRetries) {
    return {
      json: {
        ...taskData,
        approver_decision: approverDecision,
        workflow_action: 'POST_FAILURE_COMMENT'
      }
    };
  }

  // Silent retry for Approver rejection too
  console.log(`🔄 Approver retry: ${retryCount + 1}/${maxRetries}`);
  return {
    json: {
      ...taskData,
      maker_retry_count: retryCount + 1,
      approver_decision: approverDecision,
      workflow_action: 'RETRY_MAKER'
    }
  };
}

// SUCCESS!
console.log('🎉 Analysis approved!');

return {
  json: {
    ...taskData,
    checker_decision: taskData.checker_decision,
    approver_decision: approverDecision,
    final_markdown: taskData.maker_output,
    workflow_action: 'POST_SUCCESS'
  }
};

// GENERATE SUCCESS COMMENT
const taskData = $input.first().json;

const finalComment = `🎉 **DUE DILIGENCE ANALYSIS COMPLETED**\n\n` +
  `📄 **Company:** ${taskData.company_name}\n` +
  `📝 **Section:** ${taskData.section_name}\n` +
  `**Quality Score:** ${taskData.checker_decision.quality_score}/10\n` +
  `**Attempts:** ${(taskData.maker_retry_count || 0) + 1}\n` +
  `**Generated:** ${(new Date()).toISOString()}\n\n` +
  `---\n\n` +
  taskData.final_markdown +
  `\n\n---\n\n` +
  `## Quality Assurance\n\n` +
  `**Checker:** ✅ Approved (${taskData.checker_decision.quality_score}/10)\n` +
  `**Approver:** ✅ Approved\n` +
  `**Knowledge Base:** ${taskData.total_chunks} chunks\n` +
  `**User Comments:** ${taskData.user_comments_count || 0}\n` +
  `**Attachments:** ${taskData.attachments_count || 0}\n` +
  `\n⏰ **Completed:** ${(new Date()).toISOString()}`;

return {
  json: {
    ...taskData,
    final_comment: finalComment
  }
};
